out=[[1]*18 for _ in range(18)]
for r in range(6): out[r][8]=2
# axis cells
for r in (6,7): out[r][8]=7
left={6:[5,7],7:[5,6,7],8:[5,7],9:[5],10:[5]}
right={6:[10,11],7:[9,10,11,12],8:[11,12],9:[9,10,11],10:[9,10]}
for r,cs in left.items():
    for c in cs: out[r-6][c-5]=7
for r,cs in right.items():
    for c in cs: out[r-6][c+5]=7
print('\n'.join(' '.join(map(str,row)) for row in out))
